from calendar import monthrange
from datetime import date, timedelta

_WEEKDAYS = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
_MAX_YEAR = 9999


def _months(s: date, k: int):
    base = s.year * 12 + (s.month - 1)
    n = 0
    while True:
        y, m0 = divmod(base + n * k, 12)
        if y > _MAX_YEAR:
            return
        yield y, m0 + 1
        n += 1


def recur(start: str, rule: str, count: int) -> list[str]:
    s = date(*map(int, start.split("-")))
    tokens = rule.split()
    kind = tokens[0]
    result: list[date] = []

    if kind == "DAILY":
        k = int(tokens[1])
        d = s
        while len(result) < count:
            result.append(d)
            d += timedelta(days=k)

    elif kind == "WEEKLY":
        k = int(tokens[1])
        days = sorted(_WEEKDAYS[c] for c in tokens[2].split(","))
        monday = s - timedelta(days=s.weekday())
        n = 0
        while len(result) < count:
            week_start = monday + timedelta(weeks=n * k)
            for wd in days:
                d = week_start + timedelta(days=wd)
                if d >= s and len(result) < count:
                    result.append(d)
            n += 1

    elif kind == "MONTHLY" and len(tokens) == 3:
        k = int(tokens[1])
        day_spec = int(tokens[2])
        for y, m in _months(s, k):
            if len(result) >= count:
                break
            last = monthrange(y, m)[1]
            day = last if day_spec == -1 else day_spec
            if day > last:
                continue
            d = date(y, m, day)
            if d >= s:
                result.append(d)

    elif kind == "MONTHLY":
        k = int(tokens[1])
        nth = int(tokens[2])
        wd = _WEEKDAYS[tokens[3]]
        for y, m in _months(s, k):
            if len(result) >= count:
                break
            last = monthrange(y, m)[1]
            if nth > 0:
                first_wd = date(y, m, 1).weekday()
                day = 1 + (wd - first_wd) % 7 + 7 * (nth - 1)
                if day > last:
                    continue
            else:
                last_date = date(y, m, last)
                day = last - (last_date.weekday() - wd) % 7
            d = date(y, m, day)
            if d >= s:
                result.append(d)

    elif kind == "YEARLY":
        k = int(tokens[1])
        mm, dd = map(int, tokens[2].split("-"))
        n = 0
        while len(result) < count:
            y = s.year + n * k
            if y > _MAX_YEAR:
                break
            n += 1
            try:
                d = date(y, mm, dd)
            except ValueError:
                continue
            if d >= s:
                result.append(d)

    return [d.isoformat() for d in result]
